//! One audio-in audio-out exchange with Amazon Nova Sonic on Amazon Bedrock.
//!
//! Ignored and behind the `live` feature: it calls the service, which needs credentials from the
//! AWS SDK's default provider chain, model access in the region named by `AWS_REGION`, and costs
//! money. The model id is `INFERENCE_NOVA_SONIC_MODEL`, or the default of
//! [`inference_aws::nova_sonic::DEFAULT_MODEL_ID`]. Run it with
//! `cargo test -p inference-aws --features live -- --ignored`.
//!
//! It streams `tests/fixtures/question-16k.wav` (generated by eSpeak NG and SoX, the command is in
//! `tests/fixtures/question-16k.txt`) at real time followed by silence, and asserts the user
//! transcript, an assistant text, audio output and the completion. It prints the usage the service
//! reported and nothing about the account.
#![cfg(feature = "live")]

use std::time::Duration;

use inference_aws::nova_sonic::{
    ContentKind, NovaSonic, OutputEvent, Role, Session, SessionConfig, StopReason, Usage, redact,
};
use tokio::sync::oneshot;
use tokio::time::{sleep, timeout};

const CHUNK_BYTES: usize = 2048;
const CHUNK_PERIOD: Duration = Duration::from_millis(64);

fn clip_pcm() -> Vec<u8> {
    let wav = std::fs::read(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/fixtures/question-16k.wav"
    ))
    .expect("the speech clip is committed");
    let mut at = 12;
    while at + 8 <= wav.len() {
        let size =
            u32::from_le_bytes([wav[at + 4], wav[at + 5], wav[at + 6], wav[at + 7]]) as usize;
        if &wav[at..at + 4] == b"data" {
            return wav[at + 8..(at + 8 + size).min(wav.len())].to_vec();
        }
        at += 8 + size + size % 2;
    }
    panic!("the speech clip has no data chunk");
}

#[derive(Default)]
struct Seen {
    user_transcript: String,
    assistant_text: String,
    audio_bytes: usize,
    assistant_audio_ended: bool,
    interruptions: usize,
    completion_end: Option<StopReason>,
    usage: Option<Usage>,
}

#[tokio::test(flavor = "multi_thread")]
#[ignore = "calls Amazon Bedrock: needs credentials, model access and AWS_REGION, and costs money"]
async fn one_audio_in_audio_out_exchange() {
    assert!(
        std::env::var("AWS_REGION").is_ok_and(|region| !region.is_empty()),
        "set AWS_REGION to a region where the model is available"
    );
    let nova = NovaSonic::from_env().await;
    println!("model: {}", redact(nova.model_id()));
    let mut config = SessionConfig::new(
        "You are a helpful assistant in a spoken conversation. Answer in one short sentence.",
    );
    config.read_timeout = Duration::from_secs(30);
    let Session {
        mut writer,
        mut reader,
    } = nova
        .start(&config)
        .await
        .unwrap_or_else(|error| panic!("the session starts: {error}"));

    let (stop, mut stopped) = oneshot::channel::<()>();
    let pcm = clip_pcm();
    let sender = tokio::spawn(async move {
        for chunk in pcm.chunks(CHUNK_BYTES) {
            writer.send_audio(chunk).await?;
            sleep(CHUNK_PERIOD).await;
        }
        let silence = vec![0u8; CHUNK_BYTES];
        loop {
            tokio::select! {
                _ = &mut stopped => break,
                _ = sleep(CHUNK_PERIOD) => writer.send_audio(&silence).await?,
            }
        }
        writer.close().await
    });

    let mut stop = Some(stop);
    let mut seen = Seen::default();
    let exchange = async {
        while let Some(event) = reader
            .recv()
            .await
            .unwrap_or_else(|error| panic!("the service answers: {error}"))
        {
            match event {
                OutputEvent::TextOutput(text) => match text.role {
                    Some(Role::User) => seen.user_transcript.push_str(&text.content),
                    Some(Role::Assistant) => seen.assistant_text.push_str(&text.content),
                    _ => {}
                },
                OutputEvent::AudioOutput(audio) => seen.audio_bytes += audio.pcm.len(),
                OutputEvent::ContentEnd(end) if end.kind == ContentKind::Audio => {
                    seen.assistant_audio_ended = true;
                }
                OutputEvent::Interrupted { .. } => seen.interruptions += 1,
                OutputEvent::Usage(usage) => seen.usage = Some(usage),
                OutputEvent::CompletionEnd { stop_reason, .. } => {
                    seen.completion_end = Some(stop_reason);
                    break;
                }
                OutputEvent::Error(error) => panic!("the service reported {error}"),
                _ => {}
            }
            if seen.assistant_audio_ended
                && !seen.assistant_text.is_empty()
                && let Some(stop) = stop.take()
            {
                let _ = stop.send(());
            }
        }
    };
    timeout(Duration::from_secs(120), exchange)
        .await
        .expect("the exchange completes within two minutes");
    if let Some(stop) = stop.take() {
        let _ = stop.send(());
    }
    sender
        .await
        .expect("the sender task joins")
        .unwrap_or_else(|error| panic!("the input side closes cleanly: {error}"));

    println!("user transcript: {}", redact(seen.user_transcript.trim()));
    println!("assistant text: {}", redact(seen.assistant_text.trim()));
    println!("interruptions: {}", seen.interruptions);
    println!("assistant audio: {} bytes", seen.audio_bytes);
    println!("completion end: {:?}", seen.completion_end);
    match &seen.usage {
        Some(usage) => println!(
            "usage: input {} tokens (speech {}, text {}), output {} tokens (speech {}, text {}), total {}",
            usage.total_input_tokens,
            usage.total.input.speech,
            usage.total.input.text,
            usage.total_output_tokens,
            usage.total.output.speech,
            usage.total.output.text,
            usage.total_tokens
        ),
        None => println!("usage: none reported"),
    }

    assert!(!seen.user_transcript.trim().is_empty(), "a user transcript");
    assert!(
        seen.assistant_text.chars().any(char::is_alphabetic),
        "an assistant text with words in it, not only an interruption notice"
    );
    assert!(seen.audio_bytes > 0, "assistant audio output");
    assert!(seen.completion_end.is_some(), "the completion end");
}
